func (q *Queries) ListDocumentSignatureFitCompanions(ctx context.Context, arg ListDocumentSignatureFitCompanionsParams) ([]*SignatureFitCompanion, error) {
	rows, err := q.db.Query(ctx, listDocumentSignatureFitCompanions, arg.DocumentID, arg.OrgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*SignatureFitCompanion{}
	for rows.Next() {
		var i SignatureFitCompanion
		if err := rows.Scan(
			&i.SignatureID,
			&i.OrgID,
			&i.DocumentID,
			&i.RecipientID,
			&i.FieldID,
			&i.SelectionID,
			&i.SpanSha256,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

