const selectSignatureFitPreparation = `-- name: SelectSignatureFitPreparation :one
WITH parent AS MATERIALIZED (
 SELECT doc.id,doc.org_id FROM documents doc WHERE doc.id=$2 AND doc.org_id=$3
 AND doc.deleted_at IS NULL AND doc.status IN('sent','in_progress')
 AND doc.article13_notice_epoch_at=$4 AND doc.article13_notice_epoch_v61_committed FOR UPDATE OF doc
), recipient AS MATERIALIZED (
 SELECT r.id FROM recipients r JOIN parent d ON d.id=r.document_id
 WHERE r.id=$5 AND r.status IN('pending','sent','viewed') FOR UPDATE OF r
), operation AS MATERIALIZED (
 SELECT p.id, p.org_id, p.document_id, p.recipient_id, p.ceremony_epoch, p.authority_sha256, p.source_storage_key, p.source_version_id, p.source_sha256, p.source_bytes, p.geometry_sha256, p.span_sha256, p.reserved_bytes, p.expected_objects, p.owner_id, p.lease_until, p.attempts, p.status, p.selection_commit_attempted_at, p.selection_not_committed_at, p.created_at, p.updated_at, p.request_binding_creation_xid FROM signature_fit_preparations p JOIN parent d ON d.id=p.document_id AND d.org_id=p.org_id
 JOIN recipient r ON r.id=p.recipient_id WHERE p.id=$6
 AND p.ceremony_epoch=$4 AND p.authority_sha256=$7
 AND p.status='prepared' AND p.selection_commit_attempted_at IS NOT NULL AND p.selection_not_committed_at IS NULL FOR UPDATE OF p
)
INSERT INTO signature_fit_selections (
 id,preparation_id,org_id,document_id,recipient_id,ceremony_epoch,authority_sha256,
 source_storage_key,source_version_id,source_sha256,source_bytes,geometry_sha256,
 span_storage_key,span_version_id,span_sha256,span_bytes,
 manifest_storage_key,manifest_version_id,manifest_sha256,manifest_bytes,retain_until
)
SELECT $1,p.id,p.org_id,p.document_id,p.recipient_id,p.ceremony_epoch,p.authority_sha256,
 p.source_storage_key,p.source_version_id,p.source_sha256,p.source_bytes,p.geometry_sha256,
 sp.storage_key,sp.version_id,sp.sha256,sp.bytes,mf.storage_key,mf.version_id,mf.sha256,mf.bytes,
 hash_evidence_retain_until(p.ceremony_epoch,7)
FROM operation p JOIN signature_fit_objects sp ON sp.preparation_id=p.id AND sp.kind='span' AND sp.page=0
JOIN signature_fit_objects mf ON mf.preparation_id=p.id AND mf.kind='manifest' AND mf.page=0 RETURNING id, preparation_id, org_id, document_id, recipient_id, ceremony_epoch, authority_sha256, source_storage_key, source_version_id, source_sha256, source_bytes, geometry_sha256, span_storage_key, span_version_id, span_sha256, span_bytes, manifest_storage_key, manifest_version_id, manifest_sha256, manifest_bytes, retain_until, retention_started_at, retention_completed_at, created_at
`

